import {topics, questions, flashcards, examConfig} from './data.js';

const $ = (s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const emptyState=()=>({completed:[],bookmarks:[],answered:0,correct:0,quizRuns:0,bestMock:0,streak:0,lastStudy:null,lastRoute:'dashboard',theme:'dark',taglish:true,goals:[],cardsKnown:[],cardsReview:[],builder:[],mockHistory:[],lastTopic:null});
function readState(){try{const s=JSON.parse(localStorage.getItem('fieldnotes.sqa.v1')||'{}');if(!s||typeof s!=='object'||Array.isArray(s))return emptyState();const value={...emptyState(),...s};for(const k of ['completed','bookmarks','goals','cardsKnown','cardsReview','builder','mockHistory'])if(!Array.isArray(value[k]))value[k]=emptyState()[k];for(const k of ['answered','correct','quizRuns','bestMock','streak'])if(!Number.isFinite(Number(value[k]))||Number(value[k])<0)value[k]=0;if(!['dark','light'].includes(value.theme))value.theme='dark';if(typeof value.taglish!=='boolean')value.taglish=true;return value;}catch{return emptyState();}}
let state=readState();
function save(){try{localStorage.setItem('fieldnotes.sqa.v1',JSON.stringify(state));}catch{toast('Unable to save in this browser.')}}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2200);}
const titleMap={dashboard:'Dashboard',prelim:'Prelim lessons',midterm:'Midterm lessons',flashcards:'Flashcards',quiz:'Practice quiz',exams:'Mock examinations',techniques:'Testing techniques lab',builder:'Test case builder',cram:'Cram mode',analytics:'Study analytics',settings:'Settings'};
function go(route){if(!titleMap[route])route='dashboard';if(location.hash.slice(1)===route)render();else location.hash=route;}
function topicUrl(t){return `${t.lesson<=2?'prelim':'midterm'}?topic=${t.id}`;}
function topicCard(t){const done=state.completed.includes(t.id),saved=state.bookmarks.includes(t.id),list=topics.filter(x=>x.lesson===t.lesson),i=list.findIndex(x=>x.id===t.id),prev=list[i-1],next=list[i+1];return `<details class="card topic" id="${esc(t.id)}"><summary><span class="topic-number">${String(t.lesson).padStart(2,'0')}</span><span class="topic-title">${esc(t.title)}</span>${done?'<span class="badge good">Learned</span>':''}<button class="icon-action ${saved?'on':''}" data-bookmark="${esc(t.id)}" aria-label="${saved?'Remove':'Add'} bookmark">${saved?'◆':'◇'}</button></summary><div class="topic-body"><div class="topic-label">DEFINITION</div><p>${esc(t.definition)}</p>${state.taglish?`<div class="taglish"><b>Taglish</b> · ${esc(t.taglish)}</div>`:''}<div class="example-box"><b>Application example</b><br>${esc(t.example)}</div><div class="topic-label">EXAM KEYWORDS</div><p>${esc(t.keywords)}</p><div class="callout"><b>Common confusion</b><br>${esc(t.confusion)}</div><div class="topic-label">PRACTICE SITUATION · GENERATED STUDY EXERCISE</div><p>${esc(t.question)}<br><b>${esc(t.answer)}</b></p><div class="callout"><b>Quick recall</b><br>${esc(t.recall)}</div><div class="topic-actions"><button class="button small" data-complete="${esc(t.id)}">${done?'Mark for review':'Mark complete'}</button><button class="button small ghost" data-copy="${esc(t.id)}">Copy notes</button><button class="button small ghost" data-route="quiz" data-qtopic="${esc(t.id)}">Practice this concept</button></div><div class="topic-actions" style="justify-content:space-between"><button class="button small ghost" ${prev?`data-topic-open="${prev.id}"`:'disabled'}>← ${prev?'Previous topic':'Start of lesson'}</button><button class="button small ghost" ${next?`data-topic-open="${next.id}"`:'disabled'}>${next?'Next topic →':'End of lesson →'}</button></div></div></details>`;}
function header(eyebrow,title,lead,action=''){return `<div class="page-head"><div class="page-head-copy"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="lead">${lead}</p></div>${action}</div>`;}
function stat(label,value,note,icon){return `<div class="card stat-card"><div class="stat-label">${label}<span class="stat-icon">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></div>`;}
function topicProgress(list){return list.length?Math.round(list.filter(x=>state.completed.includes(x.id)).length/list.length*100):0;}
function dashboard(){const pct=Math.round(state.completed.length/topics.length*100),lessons=[1,2,3,4].map(n=>topics.filter(t=>t.lesson===n)),last=topics.find(t=>t.id===state.lastTopic)||topics.find(t=>t.lesson===1);return `${header('YOUR SQA STUDY SPACE','Ready to ace your SQA exams?',`Master software testing concepts, practice realistic situations, and build exam readiness one focused session at a time.`,'<span class="hero-tag">IT 414 / 2026</span>')}<div class="hero"><div><div class="eyebrow">CONTINUE YOUR REVIEW</div><h1 style="font-size:23px">${esc(last.title)}</h1><p class="lead">Pick up where you left off, or choose a lesson from your roadmap.</p></div><button class="button primary" data-open-topic="${last.id}">Continue learning →</button></div><div class="grid stats">${stat('Overall study progress',pct+'%',`${state.completed.length} of ${topics.length} topics completed`,'◔')}${stat('Lessons completed',`${[1,2,3,4].filter(n=>topicProgress(topics.filter(t=>t.lesson===n))===100).length} / 4`,'Completion tracks lesson topics','▤')}${stat('Practice questions',state.answered,'Answered on this device','◉')}${stat('Quiz accuracy',state.answered?Math.round(state.correct/state.answered*100)+'%':'—',state.answered?`${state.correct} correct answers`:'No quiz attempts yet','↗')}${stat('Best mock exam',state.mockHistory.length?state.bestMock+'%':'—',`${state.mockHistory.length} completed exams`,'▣')}${stat('Study streak',`${state.streak} day${state.streak===1?'':'s'}`,'Days with a completed topic or quiz','↗')}</div><div class="grid two"><section><div class="section-head"><h2>Learning roadmap</h2><a class="text-link" href="#prelim">View lessons →</a></div><div class="lesson-grid">${lessons.map((arr,i)=>{const pct=topicProgress(arr);return `<article class="card lesson-card"><div class="lesson-card-top"><span class="lesson-num">LESSON 0${i+1} · ${i<2?'PRELIM':'MIDTERM'}</span><span class="badge">${pct===100?'Complete':pct?'In progress':'Not started'}</span></div><h3>${['Testing Fundamentals','Types of Testing','Test Case Development','Testing Techniques'][i]}</h3><p>${arr.length} study topics · ${pct}% complete</p><div class="progress"><i style="width:${pct}%"></i></div><div class="lesson-meta"><span>${pct} percent</span><button class="mini-link" data-route="${i<2?'prelim':'midterm'}">Open lesson →</button></div></article>`;}).join('')}</div><div class="section-head"><h2>Upcoming study goals</h2></div><div class="card"><div id="goals-list">${goalsHtml()}</div><form class="goal-row" id="goal-form"><input class="input" name="goal" maxlength="100" placeholder="Add a personal study goal…" aria-label="New study goal" required><button class="button" type="submit">Add goal</button></form></div></section><aside><div class="section-head"><h2>Study shortcuts</h2></div><div class="card"><div class="goal-item"><span>Practice a mixed concept quiz</span><button class="mini-link" data-route="quiz">Start →</button></div><div class="goal-item"><span>Review boundary-value problems</span><button class="mini-link" data-route="techniques" data-lab="bva">Open →</button></div><div class="goal-item"><span>Build a test case</span><button class="mini-link" data-route="builder">Open →</button></div><div class="goal-item"><span>Fast topic recall</span><button class="mini-link" data-route="cram">Open →</button></div><div class="keyline"></div><p style="font-size:10px;margin:0">Progress saves only in this browser. Export/import is available in Settings.</p></div></aside></div>`;}
function goalsHtml(){return state.goals.length?state.goals.map((g,i)=>`<div class="goal-item"><label class="check-row"><input type="checkbox" data-goal-check="${i}" ${g.done?'checked':''}>${esc(g.text)}</label><button data-goal-delete="${i}" aria-label="Delete goal">×</button></div>`).join(''):'<div class="empty-state">Set a small target for your next study session.</div>';}
function lessonsPage(which){const list=topics.filter(t=>which==='prelim'?t.lesson<=2:t.lesson>=3),title=which==='prelim'?'Prelim reviewer':'Midterm reviewer',label=which==='prelim'?'PRELIM EXAM':'MIDTERM EXAM',desc=which==='prelim'?'Testing fundamentals and the types, levels, techniques, and purposes of testing.':'Test documentation and case development, plus the five core testing techniques.';return `${header(label,title,desc,`<button class="button" data-route="${which==='prelim'?'midterm':'prelim'}">Switch to ${which==='prelim'?'midterm':'prelim'} →</button>`)}<div class="lesson-layout"><section class="lesson-main">${which==='prelim'?diagrams():''}<div class="section-head"><h2>Course topics</h2><span class="badge">${state.completed.filter(id=>list.some(t=>t.id===id)).length} / ${list.length} learned</span></div>${list.map(topicCard).join('')}</section><aside class="lesson-outline card"><div class="eyebrow">ON THIS PAGE</div>${list.map(t=>`<a class="outline-link" href="#${t.id}">${esc(t.title)}</a>`).join('')}<div class="keyline"></div><p style="font-size:10px">Open any topic for its definition, Taglish note, example, exam keywords, practice scenario, and recall note.</p></aside></div>`;}
const phases=[['Requirement Analysis','Review requirements, identify testable features, and clarify details with stakeholders.','Suriin ang requirements at linawin ang hindi tiyak bago gumawa ng tests.','For enrollment, clarify prerequisites and course-capacity rules.','Clue: testable requirements and stakeholder questions.'],['Test Planning','A senior QA manager defines strategy, effort, and cost estimates for the project.','Itakda ang approach, scope, tao, oras, effort at gastos.','Estimate time for enrollment, payment, and browser coverage.','Clue: scope, resources, schedule, responsibilities.'],['Test Case Development','Create, verify, and rework test cases and scripts after the test plan is ready.','Isulat at repasuhin ang cases at scripts.','Write valid, invalid, and boundary cases for adding a course.','Clue: cases and scripts are designed.'],['Test Environment Setup','Decide the software and hardware conditions under which the work product is tested.','Ihanda ang devices, software, accounts, data at configuration.','Prepare browsers, test database, and student accounts.','Clue: environment and test conditions provisioned.'],['Test Execution','Run the software build using the prepared plans and cases.','Patakbuhin ang cases at itala ang actual results.','Run registration tests on the prepared build.','Clue: execute cases, report results and defects.'],['Test Cycle Closure','Complete execution and report completion, metrics, and results.','Ibuod ang coverage, resulta, defects at lessons learned.','Share pass/fail metrics and open defect status.','Clue: closure and completion report.']];
function diagrams(){return `<div class="card diagram"><div class="eyebrow">INTERACTIVE DIAGRAM · ORDER MATTERS</div><h2>Software Testing Life Cycle</h2><p style="font-size:11px">Select each phase to review its purpose and an exam clue.</p><div class="phase-list">${phases.map((p,i)=>`<button class="phase-button ${i===0?'active':''}" data-phase="${i}"><small>0${i+1}</small>${p[0]}</button>`).join('')}</div><div id="phase-detail" class="phase-detail"><h3>${phases[0][0]}</h3><p>${phases[0][1]}</p><p class="taglish"><b>Taglish</b> · ${phases[0][2]}</p><div class="example-box">Example: ${phases[0][3]}<br><b>${phases[0][4]}</b></div></div></div><div class="card diagram" style="margin-top:12px"><div class="eyebrow">PAIR DEVELOPMENT WITH TESTING</div><h2>V-Model relationships</h2><p style="font-size:11px">Choose a stage to see its corresponding testing level.</p><div class="vmodel"><div class="v-col"><h3>VERIFICATION · DEVELOPMENT</h3>${[['Business Requirement Analysis','Acceptance Testing'],['System Design','System Testing'],['Architectural Design','Integration Testing'],['Module Design (LLD)','Unit Testing']].map((p,i)=>`<button class="v-stage" data-vpair="${i}">${p[0]}<small>↘ planning begins here</small></button>`).join('')}<div class="v-connector">↘ CODING ↙</div></div><div class="v-col"><h3>VALIDATION · TEST LEVEL</h3>${[['User Acceptance Testing','Business needs and release readiness'],['System Testing','Complete product against requirements'],['Integration Testing','Interfaces among modules'],['Unit Testing','Individual functions or components']].map((p,i)=>`<button class="v-stage" data-vtest="${3-i}">${p[0]}<small>${p[1]}</small></button>`).join('')}</div></div><div class="result-panel" id="v-detail">Business requirements pair with Acceptance Testing. Each development stage has a corresponding planned level of testing.</div></div><div class="card diagram" style="margin-top:12px"><div class="eyebrow">SCOPE INCREASES</div><h2>Testing levels</h2><div class="phase-list">${['Unit','Integration','System','Acceptance'].map((x,i)=>`<button class="phase-button ${i===0?'active':''}" data-level="${i}"><small>0${i+1}</small>${x}</button>`).join('')}</div><div id="level-detail" class="result-panel">Individual component or function.</div></div>`;}
const levelText=['Unit: checks a function or component in isolation.','Integration: checks communication between modules.','System: checks the complete application against requirements.','Acceptance: checks user requirements and release readiness.'];
function cardsPage(){let idx=Number(sessionStorage.getItem('cardIndex')||0);if(!Number.isFinite(idx))idx=0;idx=((idx%flashcards.length)+flashcards.length)%flashcards.length;const c=flashcards[idx],flipped=sessionStorage.getItem('cardFlip')==='1';return `${header('ACTIVE RECALL','Flashcards','Recall the concept first, then reveal the quick note. Mark each card for review or as known.')}<div class="grid two"><section class="card"><div class="lesson-meta"><span>Card ${idx+1} of ${flashcards.length}</span><span>${esc(topics.find(t=>t.id===c.topic)?.title||'')}</span></div><div class="flashcard ${flipped?'flipped':''}" id="flashcard" tabindex="0" role="button" aria-label="Flip flashcard"><div class="flashcard-inner"><div class="flash-face"><span class="eyebrow">PROMPT</span><h2>${esc(c.front)}</h2><p>Think of the key idea, then reveal.</p></div><div class="flash-face flash-back"><span class="eyebrow">QUICK RECALL</span><p style="font-size:15px;color:var(--text)">${esc(c.back)}</p></div></div></div><div style="display:flex;justify-content:space-between"><button class="button" data-card-prev>← Previous</button><button class="button" data-card-flip>Flip card</button><button class="button" data-card-next>Next →</button></div></section><aside class="card"><div class="eyebrow">YOUR DECK</div><h2>Review progress</h2><p>Cards known: <b>${state.cardsKnown.length}</b> · For review: <b>${state.cardsReview.length}</b></p><div class="keyline"></div><button class="button primary" data-card-mark="known">I knew it</button> <button class="button" data-card-mark="review">Review again</button><div class="keyline"></div><p style="font-size:10px">Use the arrow buttons or keyboard left/right keys to move. Your card marks are stored locally.</p></aside></div>`;}
let quizItems=[],quizIndex=0,quizLocked=false,quizScore=0,quizFeedback='';
function startQuiz(filter){if(location.hash.split('?')[0]!=='#quiz')location.hash='quiz';quizItems=(filter?questions.filter(q=>topics.find(t=>t.id===filter)?.id===q.topic):questions).slice();if(!quizItems.length)quizItems=questions.slice();quizItems.sort(()=>Math.random()-.5);quizIndex=0;quizScore=0;quizLocked=false;quizFeedback='';state.quizRuns++;save();sessionStorage.removeItem('quiz');render();}
function quizPage(){if(!quizItems.length){try{const q=JSON.parse(sessionStorage.getItem('quiz')||'null');if(q){quizItems=q.items;quizIndex=q.index;quizScore=q.score;quizLocked=q.locked;quizFeedback=q.feedback||'';}}catch{}}if(!quizItems.length)quizItems=questions.slice(0,8);if(quizIndex>=quizItems.length)return `${header('PRACTICE COMPLETE','Quiz finished',`You scored ${quizScore} out of ${quizItems.length}. Review the explanations and try again.`)}<div class="card" style="max-width:720px"><div class="stat-value">${Math.round(quizScore/quizItems.length*100)}%</div><p>${quizScore} correct · ${quizItems.length} questions answered</p><button class="button primary" data-quiz-retry>Try a new mixed quiz</button> <button class="button" data-route="analytics">View analytics</button></div>`;const q=quizItems[quizIndex];return `${header('RETRIEVAL PRACTICE','Practice quiz','Choose the best answer. The explanation appears after you submit.')}<div class="grid two"><section class="card"><div class="lesson-meta"><span>QUESTION ${quizIndex+1} / ${quizItems.length}</span><span>Score ${quizScore}</span></div><div class="progress" style="margin-top:10px"><i style="width:${quizIndex/quizItems.length*100}%"></i></div><div class="quiz-question">${esc(q.q)}</div><div id="options">${q.choices.map((c,i)=>`<label class="answer-option ${quizLocked&&i===q.correct?'correct':''} ${quizLocked&&i===Number(sessionStorage.getItem('selectedAnswer'))&&i!==q.correct?'incorrect':''}"><input type="radio" name="answer" value="${i}" ${quizLocked&&i===Number(sessionStorage.getItem('selectedAnswer'))?'checked':''} ${quizLocked?'disabled':''}>${esc(c)}</label>`).join('')}</div>${quizFeedback?`<div class="feedback ${quizFeedback.startsWith('Correct')?'taglish':''}" role="status">${esc(quizFeedback)}</div>`:''}<div style="display:flex;justify-content:space-between;margin-top:14px">${quizLocked?'<button class="button primary" data-quiz-next>Next question →</button>':'<button class="button primary" data-quiz-submit>Check answer</button>'}<button class="button ghost" data-route="dashboard">Exit</button></div></section><aside class="card"><div class="eyebrow">STUDY TIP</div><h3>Retrieve, then review</h3><p style="font-size:11px">Commit to one answer before revealing the explanation. Use a wrong answer to identify which distinction to revisit.</p><div class="keyline"></div><p style="font-size:10px">This practice bank contains generated study questions, not official examination items.</p></aside></div>`;}
function examsPage(){return `${header('EXAM PRACTICE','Mock examinations','Practice the official exam structure described in the exam guide. All question prompts here are generated study exercises, not official exam questions.')}<div class="grid two">${Object.entries(examConfig).map(([id,e])=>`<article class="card"><div class="eyebrow">${id.toUpperCase()} · ${e.points} POINTS</div><h2 style="margin-top:9px">${e.title}</h2><p>${e.description}</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Part</th><th>Items</th><th>Points</th></tr></thead><tbody>${e.parts.map(p=>`<tr><td>${p[0]}</td><td>${p[1]}</td><td>${p[1]*p[2]}</td></tr>`).join('')}</tbody></table></div><label style="display:block;margin:0 0 10px;font-size:10px;color:var(--muted)">Optional practice timer<select class="select" data-timer="${id}" style="display:block;width:100%;margin-top:5px"><option value="60">60 minutes</option><option value="30">30 minutes</option><option value="90">90 minutes</option><option value="0">No timer</option></select></label><button class="button primary" data-exam="${id}">Start practice exam →</button></article>`).join('')}</div><div class="card" style="margin-top:14px"><div class="eyebrow">STRUCTURE NOTES</div><p style="font-size:11px;margin:8px 0 0">Prelim guide: 20 multiple choice × 2 (40), 15 situational identification × 2 (30), and a testing-plan scenario (30). Midterm guide: 10 situational identification × 2 (20), five technique analyses × 8 (40), and two practical test-case tasks × 20 (40). The PDFs do not specify exam durations; practice timer is optional and adjustable.</p></div>`;}
const prelimIds=[['What does AUT mean in the course definition of software testing?','Application Under Test'],['Which principle states that every possible input cannot be tested?','Exhaustive Testing Is Impossible'],['What is the name of the principle that links defects to a small number of modules?','Defect Clustering'],['What is the principle about repeating unchanged tests?','Pesticide Paradox'],['What can testing show, but not prove absent?','Defects'],['What is the principle that warns against software missing user needs despite few errors?','Absence-of-Errors Fallacy'],['Which principle says testing should start as early as possible?','Early Testing'],['Which principle tailors methods to product type and risk?','Testing Is Context-Dependent'],['What is the first STLC phase?','Requirement Analysis'],['What is the second STLC phase?','Test Planning'],['What is the third STLC phase?','Test Case Development'],['What is the fourth STLC phase?','Test Environment Setup'],['What is the fifth STLC phase?','Test Execution'],['What is the sixth STLC phase?','Test Cycle Closure'],['Which V-Model test level maps to module design?','Unit Testing']];
const midIds=[['What document defines organization-wide testing objectives and rules?','Test Policy'],['What document describes the overall testing approach?','Test Strategy'],['What document specifies project scope, schedule, resources, and responsibilities?','Test Plan'],['What matrix links requirements to test cases?','Requirements Traceability Matrix'],['What is a broad functionality or condition to test called?','Test Scenario'],['What records values used to execute a test?','Test Data'],['What artifact records defect description and reproduction steps?','Defect Report'],['What report summarizes activities, defects, and outcomes?','Test Summary Report'],['What field records observed behavior?','Actual Result'],['Which status indicates expected and actual differ?','Fail']];
const techniqueTasks=[['Boundary Value Analysis','A registration form accepts ages 18 through 56 inclusive. List the seven course BVA values and mark each valid or invalid.','Min−1, Min, Min+1, nominal, Max−1, Max, Max+1'],['Equivalence Class Partitioning','Scores 50–90 are valid. Identify each equivalence class and a representative value.','Below 50 invalid; 50–90 valid; above 90 invalid'],['Decision Table Testing','Registration requires valid email, eligible age, and consent. Describe conditions, rules, and the action when all are satisfied versus one is not.','Conditions/alternatives, rule combinations, allow or reject action'],['State Transition Testing','Model a login that locks after three failed attempts. Give states, triggering events, and important transitions.','Logged Out, Logged In, Locked; valid/invalid attempts; lock on third failure'],['Use Case Testing','Describe an end-to-end student enrollment use case, including actor, main flow, expected outcome, and one alternate flow.','Student actor; select section, validate, confirm, schedule; full-section alternative']];
const practicalTasks=[['Create a test case for valid student login. Include ID/title, precondition, steps, test data, expected and actual result, and status.','Must use the course columns; actual/status may be recorded during execution.'],['Create a test case for rejecting an invalid password or empty required field. Include ID/title, precondition, steps, test data, expected and actual result, and status.','Must distinguish expected from actual result and include useful negative test data.']];
function startExam(id){let items=[];if(id==='prelim'){const mc=questions.slice(0,12);while(mc.length<20)mc.push(questions[mc.length%questions.length]);items=mc.map((q,i)=>({kind:'mc',q:q.q,choices:q.choices,correct:q.correct,points:2,section:'Multiple Choice'}));prelimIds.forEach(([q,guide])=>items.push({kind:'identify',q,guide,points:2,section:'Situational Identification'}));items.push({kind:'scenario',q:'Scenario: A university launches an online enrollment portal. Design a testing plan using at least five different testing types. For each type, give a specific scenario and state what you intend to verify.',guide:'A useful answer names five distinct types, gives a concrete situation for each, and states a verification goal. Example types: functional, security, compatibility, load, usability, regression.',points:30,section:'Testing Plan Scenario'});}else{midIds.forEach(([q,guide])=>items.push({kind:'identify',q,guide,points:2,section:'Situational Identification'}));techniqueTasks.forEach(([name,q,guide])=>items.push({kind:'analysis',q:`${name}: ${q}`,guide,points:8,section:'Testing Techniques Analysis'}));practicalTasks.forEach(([q,guide])=>items.push({kind:'practical',q,guide,points:20,section:'Practical Test Case Creation'}));}const timer=Number($(`[data-timer="${id}"]`)?.value??60);sessionStorage.setItem('mock',JSON.stringify({id,items,index:0,answers:[],scores:[],started:Date.now(),deadline:timer?Date.now()+timer*60000:null}));render();}
function mockPage(){let m;try{m=JSON.parse(sessionStorage.getItem('mock')||'null')}catch{}if(!m)return examsPage();if(m.index>=m.items.length){const earned=m.scores.reduce((a,b)=>a+(Number(b)||0),0),total=m.items.reduce((n,x)=>n+x.points,0);state.bestMock=Math.max(state.bestMock,Math.round(earned/total*100));state.mockHistory.push({id:m.id,earned,total,date:new Date().toISOString()});save();sessionStorage.removeItem('mock');return `${header('PRACTICE COMPLETE',`${examConfig[m.id].title} completed`,`Your result is ${earned} of ${total} points. Generated practice material; verify course details against instructor notes.`)}<div class="card" style="max-width:700px"><div class="stat-value">${earned} / ${total}</div><p>${Math.round(earned/total*100)}% · Best mock score: ${state.bestMock}%</p><button class="button primary" data-route="exams">Back to mock examinations</button></div>`;}const item=m.items[m.index],answer=m.answers[m.index]??'',timer=m.deadline?`<span class="badge" id="exam-clock">--:-- remaining</span>`:'';return `${header(`${m.id.toUpperCase()} MOCK · ${item.points} POINTS`,`Question ${m.index+1} of ${m.items.length}`,`${item.section} · ${m.answers.filter(x=>x!==undefined).length} answered · Auto-saved in this tab`,timer)}<div class="card" style="max-width:740px"><div class="quiz-question">${esc(item.q)}</div>${item.kind==='mc'?item.choices.map((c,i)=>`<label class="answer-option"><input type="radio" name="mock-answer" value="${i}" ${answer===i?'checked':''}>${esc(c)}</label>`).join(''):`<textarea class="textarea" id="mock-text" style="width:100%;min-height:160px" placeholder="Write your answer, analysis, or test case here…">${esc(answer)}</textarea><div class="callout" style="margin-top:12px"><b>Self-check guide</b><br>${esc(item.guide)}</div><label style="display:block;margin-top:12px;font-size:10px;color:var(--muted)">Self-assessed points (0–${item.points})<input class="input" type="number" min="0" max="${item.points}" id="mock-score" value="${m.scores[m.index]??0}" style="display:block;width:100%;margin-top:5px"></label>`}<div style="display:flex;justify-content:space-between;margin-top:15px"><button class="button" data-mock-prev ${m.index===0?'disabled':''}>← Previous</button><button class="button primary" data-mock-next>${m.index===m.items.length-1?'Submit exam':'Save & Next →'}</button></div><p style="font-size:9px;margin:12px 0 0">Written sections are self-assessed with the supplied checklist; responses stay in this tab's session.</p></div>`;}
function techniquesPage(){return `${header('HANDS-ON PRACTICE','Testing techniques lab','Try the structured techniques from Lesson IV. These tools illustrate the method; confirm the requirement and expected behavior for each problem.')}<div class="tech-tabs">${[['bva','Boundary values'],['ecp','Equivalence classes'],['decision','Decision table'],['state','State transitions'],['usecase','Use case']].map((x,i)=>`<button class="tech-tab ${i===0?'active':''}" data-tech="${x[0]}">${x[1]}</button>`).join('')}</div><div id="tech-panel"></div>`;}
let activeTech='bva';
function techContent(id){activeTech=id;const common=`<div class="card">`;if(id==='bva')return `${common}<div class="eyebrow">BOUNDARY VALUE ANALYSIS</div><h2>Generate range checks</h2><p>For inclusive integer limits, calculate Min−1, Min, Min+1, a nominal value, Max−1, Max, Max+1.</p><div class="grid three"><label>Minimum<input class="input" type="number" id="bva-min" value="18"></label><label>Maximum<input class="input" type="number" id="bva-max" value="56"></label><label>Nominal (optional)<input class="input" type="number" id="bva-nom" placeholder="Auto midpoint"></label></div><button class="button primary" style="margin-top:12px" data-calc="bva">Calculate values</button><div id="tech-result" class="result-panel">Inclusive range example: 18–56 → 17, 18, 19, 37, 55, 56, 57.</div></div>`;
if(id==='ecp')return `${common}<div class="eyebrow">EQUIVALENCE CLASS PARTITIONING</div><h2>Visualize valid ranges</h2><p>Provide one or more inclusive valid integer ranges (comma-separated, such as 1-10, 20-30).</p><label>Valid ranges<input class="input" id="ecp-ranges" value="1-10, 20-30" style="display:block;width:100%;margin:6px 0 12px"></label><button class="button primary" data-calc="ecp">Build partitions</button><div id="tech-result" class="result-panel">Five classes: below 1 (invalid), 1–10 (valid), 11–19 (invalid), 20–30 (valid), above 30 (invalid).</div></div>`;
if(id==='decision')return `${common}<div class="eyebrow">DECISION TABLE BUILDER</div><h2>Condition combinations</h2><p>Choose up to four Boolean conditions, then assign an action for each generated rule.</p><label>Conditions (comma-separated)<input class="input" id="decision-conditions" value="Email valid, Age eligible, Consent given" style="display:block;width:100%;margin:6px 0 12px"></label><button class="button primary" data-calc="decision">Generate decision table</button><div id="tech-result" class="result-panel">Example: registration allowed only when all required conditions are true.</div></div>`;
if(id==='state')return `${common}<div class="eyebrow">STATE TRANSITION SIMULATOR</div><h2>Login lockout example</h2><p>Valid credentials sign in. Three failures lock the account. Reset to start another sequence.</p><div class="lesson-meta"><span>Current state: <b id="login-state">Logged Out</b></span><span>Failed attempts: <b id="login-attempts">0</b> / 3</span></div><div class="tech-tabs"><button class="button primary" data-login="valid">Submit valid credentials</button><button class="button" data-login="invalid">Submit invalid credentials</button><button class="button ghost" data-login="reset">Reset simulation</button></div><div id="tech-result" class="result-panel">Start in Logged Out. Each invalid attempt is an event that can change the state.</div></div>`;
return `${common}<div class="eyebrow">USE CASE SIMULATOR</div><h2>Student course enrollment</h2><p>Actor: Student · Goal: enroll in an available course section.</p><div id="usecase-flow" class="callout">Begin the flow to see main and alternate outcomes.</div><div class="tech-tabs"><button class="button primary" data-flow="next">Next step →</button><button class="button" data-flow="alternate">Section full (alternate)</button><button class="button ghost" data-flow="reset">Reset flow</button></div><div id="tech-result" class="result-panel">An end-to-end use case covers actor, goal, interactions, and expected outcome.</div></div>`;}
function builderPage(){return `${header('PRACTICAL EXAM PREP','Test case builder','Create, edit, delete, and export structured test cases. Drafts are saved locally in this browser.','<button class="button" data-export="cases">Export CSV</button>')}<div class="grid two"><form class="card" id="case-form"><div class="eyebrow">CASE DETAILS</div><input type="hidden" name="editId"><div class="builder-grid" style="margin-top:13px"><label>ID<input class="input" name="id" maxlength="24" required placeholder="TC-001"></label><label>Test Case Title<input class="input" name="title" maxlength="100" required></label><label class="full">Preconditions<textarea class="textarea" name="pre" maxlength="500"></textarea></label><label class="full">Test Steps<textarea class="textarea" name="steps" maxlength="800" required></textarea></label><label class="full">Test Data<textarea class="textarea" name="data" maxlength="500"></textarea></label><label class="full">Expected Results<textarea class="textarea" name="expected" maxlength="500" required></textarea></label><label class="full">Actual Results<textarea class="textarea" name="actual" maxlength="500"></textarea></label><label class="full">Postconditions (optional)<textarea class="textarea" name="post" maxlength="500"></textarea></label><label>Status<select class="select" name="status"><option>Not Run</option><option>Pass</option><option>Fail</option><option>Blocked</option></select></label></div><button class="button primary" style="margin-top:14px" type="submit">Save test case</button><button class="button ghost" type="reset" id="case-cancel">Clear</button></form><section class="card"><div class="eyebrow">SAVED CASES</div><h2>Your test cases <span class="badge" id="case-count">${state.builder.length}</span></h2><div id="case-list">${caseList()}</div></section></div>`;}
function caseList(){return state.builder.length?state.builder.map((c,i)=>`<div class="goal-item" style="display:block"><div style="display:flex;justify-content:space-between;gap:8px"><b>${esc(c.id)} · ${esc(c.title)}</b><span class="badge ${c.status==='Pass'?'good':''}">${esc(c.status)}</span></div><small style="display:block;color:var(--muted);margin-top:7px">Steps: ${esc(c.steps)}<br>Expected: ${esc(c.expected)}<br>Actual: ${esc(c.actual||'Not recorded')}${c.post?`<br>Postcondition: ${esc(c.post)}`:''}</small><div style="margin-top:7px"><button class="mini-link" data-case-edit="${i}">Edit</button> <button class="mini-link" data-case-delete="${i}">Delete</button></div></div>`).join(''):'<div class="empty-state">No cases yet. Add one using the course columns.</div>';}
function cramPage(){const essentials=topics.filter(t=>['principle-exhaustive','principle-clustering','principle-pesticide','principle-presence','principle-fallacy','principle-early','principle-context','stlc','vmodel','levels','smoke-sanity','retest-regression','performance-types','test-policy-strategy-plan','test-case-fields','bva','ecp','decision-table','state-transition','use-case','error-guessing'].includes(t.id));return `${header('QUICK RECALL','Cram mode','A compact last-pass review of high-yield terms, orders, and distinctions. Expand any note for the full topic.')}<div class="card" style="margin-bottom:13px"><div class="eyebrow">REMEMBER THE ORDER</div><h2>Seven principles</h2><p>Exhaustive testing is impossible → Defect clustering → Pesticide paradox → Testing shows presence of defects → Absence-of-errors fallacy → Early testing → Context-dependent testing.</p><h2>Six STLC phases</h2><p>Requirement Analysis → Test Planning → Test Case Development → Test Environment Setup → Test Execution → Test Cycle Closure.</p></div>${essentials.map(topicCard).join('')}`;}
function analyticsPage(){const pct=Math.round(state.completed.length/topics.length*100),accuracy=state.answered?Math.round(state.correct/state.answered*100):0;return `${header('YOUR ACTIVITY','Study analytics','A snapshot calculated from your saved learning activity. No progress values are prefilled.')}<div class="grid stats">${stat('Topic completion',pct+'%',`${state.completed.length} / ${topics.length} topics`,'◔')}${stat('Questions answered',state.answered,`${state.quizRuns} quiz sessions`,'◉')}${stat('Quiz accuracy',state.answered?accuracy+'%':'—',`${state.correct} correct`,'↗')}${stat('Best mock exam',state.mockHistory.length?state.bestMock+'%':'—',`${state.mockHistory.length} completed`,'▣')}</div><div class="grid two"><div class="card"><div class="eyebrow">LESSON COMPLETION</div><h2>Progress by lesson</h2>${[1,2,3,4].map(n=>{const arr=topics.filter(t=>t.lesson===n),p=topicProgress(arr);return `<div style="margin:16px 0"><div class="lesson-meta"><span>Lesson ${n} · ${['Testing Fundamentals','Types of Testing','Test Case Development','Testing Techniques'][n-1]}</span><b>${p}%</b></div><div class="progress" style="margin-top:6px"><i style="width:${p}%"></i></div></div>`}).join('')}</div><div class="card"><div class="eyebrow">STUDY PREFERENCES</div><h2>Activity notes</h2><p>Flashcards marked known: ${state.cardsKnown.length}</p><p>Flashcards for review: ${state.cardsReview.length}</p><p>Personal goals: ${state.goals.filter(g=>!g.done).length} active</p><p>Current study streak: ${state.streak} days</p><p style="font-size:10px">The current streak updates on days you complete a topic or answer a practice question.</p></div></div>`;}
function settingsPage(){return `${header('PREFERENCES','Settings','Manage your display, language, and locally saved study data.')}<div class="grid two"><div class="card"><div class="eyebrow">DISPLAY</div><h2>Appearance</h2><label class="check-row"><input type="checkbox" id="light-setting" ${state.theme==='light'?'checked':''}> Use light theme</label><div class="keyline"></div><label class="check-row"><input type="checkbox" id="taglish-setting" ${state.taglish?'checked':''}> Show Taglish explanations in lessons</label><p style="font-size:10px;margin-top:12px">Theme and language preference save in this browser.</p></div><div class="card"><div class="eyebrow">DATA ON THIS DEVICE</div><h2>Export or reset</h2><p>Study progress and test cases stay in this browser. Export a JSON backup to move your data manually.</p><button class="button" data-export="backup">Export backup</button> <label class="button" for="import-file" style="display:inline-block;cursor:pointer">Import backup<input id="import-file" type="file" accept="application/json" hidden></label><div class="keyline"></div><button class="button" data-reset>Reset all progress</button></div></div>`;}
function page(route){switch(route){case'dashboard':return dashboard();case'prelim':return lessonsPage('prelim');case'midterm':return lessonsPage('midterm');case'flashcards':return cardsPage();case'quiz':return quizPage();case'exams':return mockPageOrList();case'techniques':return techniquesPage();case'builder':return builderPage();case'cram':return cramPage();case'analytics':return analyticsPage();case'settings':return settingsPage();default:return dashboard();}}
function mockPageOrList(){return sessionStorage.getItem('mock')?mockPage():examsPage();}
let examTimer=null;
function render(){clearInterval(examTimer);let route=location.hash.slice(1).split('?')[0]||'dashboard';if(!titleMap[route])route='dashboard';$('#view').innerHTML=page(route);$('#page-name').textContent=titleMap[route];$$('[data-route]').forEach(a=>a.classList.toggle('active',a.dataset.route===route));state.lastRoute=route;save();if(route==='techniques')$('#tech-panel').innerHTML=techContent(activeTech);if(route==='prelim'||route==='cram'){const q=new URLSearchParams(location.hash.split('?')[1]||'').get('topic');if(q){setTimeout(()=>{$(`#${CSS.escape(q)}`)?.setAttribute('open','');$(`#${CSS.escape(q)}`)?.scrollIntoView({behavior:'smooth',block:'start'});},60);}}if(route==='exams'&&sessionStorage.getItem('mock')){examTimer=setInterval(()=>{let m;try{m=JSON.parse(sessionStorage.getItem('mock')||'null')}catch{}if(!m||!m.deadline)return;const left=Math.max(0,Math.ceil((m.deadline-Date.now())/1000)),clock=$('#exam-clock');if(clock)clock.textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;if(left===0){const field=$('#mock-text');if(field&&m.answers[m.index]===undefined)m.answers[m.index]=field.value.trim();m.index=m.items.length;sessionStorage.setItem('mock',JSON.stringify(m));render();}},1000);}}
function updateStreak(){const now=new Date(),today=new Date(now.getTime()-now.getTimezoneOffset()*60000).toISOString().slice(0,10),last=state.lastStudy;if(last!==today){if(last&&Math.round((Date.parse(today)-Date.parse(last))/86400000)===1)state.streak++;else if(!last||Math.round((Date.parse(today)-Date.parse(last))/86400000)>1)state.streak=1;state.lastStudy=today;}save();}
function download(name,data,type){const blob=new Blob([data],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function csvCell(s){let v=String(s??'');if(/^[=+@\-\t\r]/.test(v))v="'"+v;return '"'+v.replaceAll('"','""')+'"';}
function buildBva(){const min=Number($('#bva-min').value),max=Number($('#bva-max').value);if(!Number.isInteger(min)||!Number.isInteger(max)||min>=max){$('#tech-result').textContent='Enter whole-number limits where minimum is less than maximum.';return;}let nominal=$('#bva-nom').value===''?Math.floor((min+max)/2):Number($('#bva-nom').value);if(!Number.isInteger(nominal)||nominal<min||nominal>max){$('#tech-result').textContent='Nominal must be a whole number within the valid range.';return;}const vals=[min-1,min,min+1,nominal,max-1,max,max+1];$('#tech-result').innerHTML=`<div class="table-wrap"><table class="data-table"><thead><tr><th>Position</th><th>Value</th><th>Expected</th></tr></thead><tbody>${['Min − 1','Min','Min + 1','Nominal','Max − 1','Max','Max + 1'].map((x,i)=>`<tr><td>${x}</td><td>${vals[i]}</td><td>${i===0||i===6?'Invalid':'Valid'}</td></tr>`).join('')}</tbody></table></div>`;}
function buildEcp(){const raw=$('#ecp-ranges').value.split(',').map(x=>x.trim()).filter(Boolean),ranges=[];for(const s of raw){const m=s.match(/^(-?\d+)\s*[-–]\s*(-?\d+)$/);if(!m){$('#tech-result').textContent=`Could not parse “${s}”. Use inclusive ranges such as 1-10.`;return;}const a=+m[1],b=+m[2];if(a>b){$('#tech-result').textContent=`Range ${s} has minimum greater than maximum.`;return;}ranges.push([a,b]);}ranges.sort((a,b)=>a[0]-b[0]);if(!ranges.length||ranges.some((r,i)=>i&&r[0]<=ranges[i-1][1])){$('#tech-result').textContent='Enter at least one range. Ranges must not overlap.';return;}let rows=[['Below '+ranges[0][0],`≤ ${ranges[0][0]-1}`,'Invalid']];ranges.forEach((r,i)=>{rows.push([`Valid range ${i+1}`,`${r[0]}–${r[1]}`,'Valid']);if(i<ranges.length-1)rows.push(['Gap',`${r[1]+1}–${ranges[i+1][0]-1}`,'Invalid']);});rows.push(['Above '+ranges.at(-1)[1],`≥ ${ranges.at(-1)[1]+1}`,'Invalid']);$('#tech-result').innerHTML=`<p>${rows.length} equivalence classes</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Class</th><th>Values</th><th>Expected</th></tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function buildDecision(){const cond=$('#decision-conditions').value.split(',').map(x=>x.trim()).filter(Boolean).slice(0,4);if(!cond.length){$('#tech-result').textContent='Add at least one condition.';return;}const rules=2**cond.length,acts=[];for(let i=0;i<rules;i++)acts.push(cond.every((_,j)=>(i>>(cond.length-j-1))&1)?'Allow':'Reject');$('#tech-result').innerHTML=`<div class="table-wrap"><table class="data-table"><thead><tr><th>Rule</th>${cond.map(c=>`<th>${esc(c)}</th>`).join('')}<th>Action</th></tr></thead><tbody>${Array.from({length:rules},(_,i)=>`<tr><td>R${i+1}</td>${cond.map((_,j)=>`<td>${(i>>(cond.length-j-1))&1?'Yes':'No'}</td>`).join('')}<td>${acts[i]}</td></tr>`).join('')}</tbody></table></div><small>${rules} possible Boolean rules generated. Action shown is a sample all-conditions-required rule.</small>`;}
function setTheme(theme){state.theme=theme;document.documentElement.dataset.theme=theme;save();}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a,[role=button]');if(!b)return;
 if(b.dataset.route){e.preventDefault();if(b.dataset.qtopic){startQuiz(b.dataset.qtopic);return;}if(b.dataset.lab){activeTech=b.dataset.lab;go(b.dataset.route);return;}go(b.dataset.route);$('#sidebar').classList.remove('open');$('#scrim').classList.remove('show');return;}
 if(b.dataset.openTopic){const t=topics.find(x=>x.id===b.dataset.openTopic);if(t){state.lastTopic=t.id;save();location.hash=topicUrl(t);}return;}
 if(b.dataset.complete){const id=b.dataset.complete;state.completed=state.completed.includes(id)?state.completed.filter(x=>x!==id):[...state.completed,id];if(state.completed.includes(id)){state.lastTopic=id;updateStreak();toast('Topic marked complete');}save();render();return;}
 if(b.dataset.bookmark){e.preventDefault();e.stopPropagation();const id=b.dataset.bookmark;state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];save();render();return;}
 if(b.dataset.topicOpen){const t=topics.find(x=>x.id===b.dataset.topicOpen);if(t){state.lastTopic=t.id;save();location.hash=topicUrl(t);}return;}
 if(b.dataset.copy){const t=topics.find(x=>x.id===b.dataset.copy);const text=`${t.title}\n${t.definition}\nTaglish: ${t.taglish}\nExample: ${t.example}\nKeywords: ${t.keywords}\nRecall: ${t.recall}`;try{await navigator.clipboard.writeText(text);toast('Notes copied');}catch{toast('Clipboard is unavailable in this browser');}return;}
 if(b.dataset.phase!==undefined){$$('[data-phase]').forEach(x=>x.classList.toggle('active',x===b));const p=phases[+b.dataset.phase];$('#phase-detail').innerHTML=`<h3>${p[0]}</h3><p>${p[1]}</p><p class="taglish"><b>Taglish</b> · ${p[2]}</p><div class="example-box">Example: ${p[3]}<br><b>${p[4]}</b></div>`;return;}
 if(b.dataset.vpair!==undefined||b.dataset.vtest!==undefined){const i=+(b.dataset.vpair??b.dataset.vtest),pairs=[['Business Requirement Analysis','Acceptance Testing'],['System Design','System Testing'],['Architectural Design','Integration Testing'],['Module Design (LLD)','Unit Testing']];$$('[data-vpair],[data-vtest]').forEach(x=>x.classList.toggle('selected',+(x.dataset.vpair??x.dataset.vtest)===i));$('#v-detail').textContent=`${pairs[i][0]} ↔ ${pairs[i][1]}. The development activity defines expected behavior early; its paired test level checks corresponding needs at validation.`;return;}
 if(b.dataset.level!==undefined){$$('[data-level]').forEach(x=>x.classList.toggle('active',x===b));$('#level-detail').textContent=levelText[+b.dataset.level];return;}
 if(b.dataset.cardFlip!==undefined||b.id==='flashcard'){const el=$('#flashcard');el.classList.toggle('flipped');sessionStorage.setItem('cardFlip',el.classList.contains('flipped')?'1':'0');return;}
 if(b.dataset.cardPrev!==undefined||b.dataset.cardNext!==undefined){let i=Number(sessionStorage.getItem('cardIndex')||0);i=(i+(b.dataset.cardNext!==undefined?1:-1)+flashcards.length)%flashcards.length;sessionStorage.setItem('cardIndex',i);sessionStorage.setItem('cardFlip','0');render();return;}
 if(b.dataset.cardMark){let i=Number(sessionStorage.getItem('cardIndex')||0),id=flashcards[i].topic;const arr=b.dataset.cardMark==='known'?'cardsKnown':'cardsReview',other=arr==='cardsKnown'?'cardsReview':'cardsKnown';state[arr]=[...new Set([...state[arr],id])];state[other]=state[other].filter(x=>x!==id);save();toast('Card progress saved');render();}
 if(b.dataset.quizSubmit!==undefined){const checked=$('input[name=answer]:checked');if(!checked){toast('Choose an answer first');return;}const i=+checked.value,q=quizItems[quizIndex];sessionStorage.setItem('selectedAnswer',String(i));quizLocked=true;const good=i===q.correct;quizScore+=good?1:0;state.answered++;if(good)state.correct++;updateStreak();const topic=topics.find(t=>t.id===q.topic);quizFeedback=`${good?'Correct.':'Not quite.'} ${q.why||topic?.answer||''}`;sessionStorage.setItem('quiz',JSON.stringify({items:quizItems,index:quizIndex,score:quizScore,locked:quizLocked,feedback:quizFeedback}));save();render();return;}
 if(b.dataset.quizNext!==undefined){quizIndex++;quizLocked=false;quizFeedback='';sessionStorage.setItem('quiz',JSON.stringify({items:quizItems,index:quizIndex,score:quizScore,locked:false}));render();return;}
 if(b.dataset.quizRetry!==undefined){startQuiz();return;}
 if(b.dataset.exam){startExam(b.dataset.exam);return;}
 if(b.dataset.mockNext!==undefined){let m=JSON.parse(sessionStorage.getItem('mock')),item=m.items[m.index];if(item.kind==='mc'){const a=$('input[name=mock-answer]:checked');if(a)m.answers[m.index]=+a.value;else if(m.answers[m.index]===undefined){toast('Choose an answer before continuing');return;}m.scores[m.index]=m.answers[m.index]===item.correct?item.points:0;}else{const response=$('#mock-text').value.trim();if(!response){toast('Write a response before continuing');return;}const score=Number($('#mock-score').value);if(!Number.isFinite(score)||score<0||score>item.points){toast(`Enter a score from 0 to ${item.points}`);return;}m.answers[m.index]=response;m.scores[m.index]=score;}m.index++;sessionStorage.setItem('mock',JSON.stringify(m));render();return;}
 if(b.dataset.mockPrev!==undefined){let m=JSON.parse(sessionStorage.getItem('mock'));if(m.index>0){const item=m.items[m.index];if(item.kind!=='mc'&&$('#mock-text')){m.answers[m.index]=$('#mock-text').value;m.scores[m.index]=Number($('#mock-score').value)||0;}}m.index=Math.max(0,m.index-1);sessionStorage.setItem('mock',JSON.stringify(m));render();return;}
 if(b.dataset.tech){activeTech=b.dataset.tech;$$('.tech-tab').forEach(x=>x.classList.toggle('active',x.dataset.tech===activeTech));$('#tech-panel').innerHTML=techContent(activeTech);return;}
 if(b.dataset.calc==='bva'){buildBva();return;}if(b.dataset.calc==='ecp'){buildEcp();return;}if(b.dataset.calc==='decision'){buildDecision();return;}
 if(b.dataset.login){let stateBox=$('#login-state'),att=$('#login-attempts'),out=$('#tech-result'),a=Number(att.textContent);let st=stateBox.textContent;if(b.dataset.login==='reset'){stateBox.textContent='Logged Out';att.textContent='0';out.textContent='Simulation reset to Logged Out.';}else if(st==='Locked'){out.textContent='Account is Locked. Reset or perform account recovery before signing in.';}else if(b.dataset.login==='valid'){stateBox.textContent='Logged In';out.textContent='Valid credentials: Logged Out → Logged In.';}else{a++;att.textContent=a;if(a>=3){stateBox.textContent='Locked';out.textContent='Third failed attempt: Logged Out → Locked. Further credentials are rejected.';}else out.textContent=`Invalid credentials: remain Logged Out (${a} failed attempt${a>1?'s':''}).`;}return;}
 if(b.dataset.flow){let i=Number($('#usecase-flow').dataset.step||0),flow=['Student opens enrollment','Student selects a course section','System checks prerequisites and seat availability','Student confirms enrollment','System records enrollment and displays schedule'];if(b.dataset.flow==='reset'){i=0;$('#tech-result').textContent='Flow reset.';}else if(b.dataset.flow==='alternate'){i=2;$('#tech-result').textContent='Alternate flow: section is full; system explains no seat is available and prompts the student to choose another section.';}else{i=Math.min(i+1,flow.length);$('#tech-result').textContent=i===flow.length?'Expected outcome: enrollment is recorded and a schedule is displayed.':`Expected next interaction: ${flow[i]}.`;}$('#usecase-flow').dataset.step=i;$('#usecase-flow').textContent=i===0?'Begin with the student actor and enrollment goal.':flow[Math.min(i-1,flow.length-1)];return;}
 if(b.dataset.caseDelete!==undefined){state.builder.splice(+b.dataset.caseDelete,1);save();render();return;}
 if(b.dataset.caseEdit!==undefined){const c=state.builder[+b.dataset.caseEdit],f=$('#case-form');for(const k of ['id','title','pre','steps','data','expected','actual','post','status'])f.elements[k].value=c[k]||'';f.elements.editId.value=c._key;f.querySelector('[type=submit]').textContent='Update test case';f.scrollIntoView({behavior:'smooth'});return;}
 if(b.dataset.export==='cases'){const cols=['ID','Test Case Title','Preconditions','Test Steps','Test Data','Expected Results','Actual Results','Postconditions','Status'];download('sqa-test-cases.csv',[cols,...state.builder.map(c=>[c.id,c.title,c.pre,c.steps,c.data,c.expected,c.actual,c.post,c.status])].map(row=>row.map(csvCell).join(',')).join('\r\n'),'text/csv');return;}
 if(b.dataset.export==='backup'){download('fieldnotes-sqa-progress.json',JSON.stringify(state,null,2),'application/json');return;}
 if(b.dataset.reset){if(confirm('Reset all saved progress, bookmarks, goals, and test cases in this browser?')){localStorage.removeItem('fieldnotes.sqa.v1');state=emptyState();setTheme('dark');render();toast('Progress reset');}return;}
 if(b.dataset.goalDelete!==undefined){state.goals.splice(+b.dataset.goalDelete,1);save();render();return;}
});
document.addEventListener('submit',e=>{if(e.target.id==='goal-form'){e.preventDefault();const text=new FormData(e.target).get('goal').trim();if(text){state.goals.push({text,done:false});save();render();}}if(e.target.id==='case-form'){e.preventDefault();const f=e.target,data=Object.fromEntries(new FormData(f));const key=data.editId||crypto.randomUUID();const idx=state.builder.findIndex(c=>c._key===key);const duplicate=state.builder.some(c=>c.id.trim().toLowerCase()===data.id.trim().toLowerCase()&&c._key!==key);if(duplicate){toast('That test case ID is already in use');return;}const item={...data,_key:key};if(idx>=0)state.builder[idx]=item;else state.builder.push(item);save();render();toast(idx>=0?'Test case updated':'Test case saved');}});
document.addEventListener('input',e=>{if(e.target.id==='mock-text'){try{const m=JSON.parse(sessionStorage.getItem('mock'));if(m){m.answers[m.index]=e.target.value;sessionStorage.setItem('mock',JSON.stringify(m));}}catch{}}});
document.addEventListener('change',e=>{if(e.target.matches('[data-goal-check]')){const g=state.goals[+e.target.dataset.goalCheck];g.done=e.target.checked;save();render();}if(e.target.id==='light-setting')setTheme(e.target.checked?'light':'dark');if(e.target.id==='taglish-setting'){state.taglish=e.target.checked;save();render();}if(e.target.id==='import-file'&&e.target.files[0]){const reader=new FileReader();reader.onload=()=>{try{const incoming=JSON.parse(reader.result);if(!incoming||typeof incoming!=='object'||Array.isArray(incoming))throw Error();const next={...emptyState(),...incoming};for(const k of ['completed','bookmarks','goals','cardsKnown','cardsReview','builder','mockHistory'])if(!Array.isArray(next[k]))throw Error();if(!['dark','light'].includes(next.theme))next.theme='dark';state=next;save();setTheme(state.theme);render();toast('Backup imported');}catch{toast('Invalid backup file');}};reader.readAsText(e.target.files[0]);}});
$('#theme-toggle').addEventListener('click',()=>setTheme(state.theme==='dark'?'light':'dark'));
$('#menu-toggle').addEventListener('click',()=>{$('#sidebar').classList.add('open');$('#scrim').classList.add('show');});$('#scrim').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#scrim').classList.remove('show');});
$('#search').addEventListener('input',e=>{const q=e.target.value.trim().toLowerCase();let box=$('#search-results');if(!box){box=document.createElement('div');box.id='search-results';box.className='search-results';$('.topbar').append(box);}if(q.length<2){box.classList.remove('show');return;}const hits=topics.filter(t=>(t.title+' '+t.definition+' '+t.keywords).toLowerCase().includes(q)).slice(0,8);box.innerHTML=hits.length?hits.map(t=>`<a class="search-hit" href="#${topicUrl(t)}"><b>${esc(t.title)}</b><small>Lesson ${t.lesson} · ${esc(t.definition.slice(0,95))}…</small></a>`).join(''):'<div class="empty-state">No matching course topics.</div>';box.classList.add('show');});
document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap')&&!e.target.closest('.search-results'))$('#search-results')?.classList.remove('show');});
window.addEventListener('hashchange',render);window.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#search').focus();}if(location.hash.includes('flashcards')&&(e.key==='ArrowLeft'||e.key==='ArrowRight')){const btn=$(`[data-card-${e.key==='ArrowLeft'?'prev':'next'}]`);btn?.click();}if(e.key==='Escape'){$('#sidebar').classList.remove('open');$('#scrim').classList.remove('show');$('#search-results')?.classList.remove('show');}});
document.documentElement.dataset.theme=state.theme;
// Support deep links from search results using #route?topic=id.
render();
